SELECT 
FROM evaluation_tasks
WHERE organization_uuid = #{params.OrganizationUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
ORDER BY created_at DESC, uuid DESC
LIMIT #{params.Limit} OFFSET #{params.Offset}

SELECT 
