AND workspace_uuid = #{params.WorkspaceUUID}
AND task_uuid IN
#{taskUUID}
ORDER BY task_uuid ASC, round ASC, position ASC

SELECT 
FROM evaluation_task_scores
WHERE organization_uuid = #{params.OrganizationUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
AND task_uuid IN
#{taskUUID}
ORDER BY task_uuid ASC, created_at ASC

SELECT 
FROM evaluation_task_scores
WHERE organization_uuid = #{organizationUUID}
AND workspace_uuid = #{workspaceUUID}
AND task_uuid = #{taskUUID}
ORDER BY created_at ASC

SELECT 
FROM evaluation_task_items
WHERE organization_uuid = #{organizationUUID}
AND workspace_uuid = #{workspaceUUID}
AND session_external_id = #{sessionExternalID}
AND status = 'running'

mapper.update:
UPDATE evaluation_task_items
SET status = 'running',
    session_external_id = '',
    error_message = '',
    updated_at = #{params.UpdatedAt}
WHERE uuid = #{params.UUID}
AND organization_uuid = #{params.OrganizationUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
AND status = 'pending'

UPDATE evaluation_task_items
SET session_external_id = #{params.SessionExternalID},
    updated_at = #{params.UpdatedAt}
WHERE uuid = #{params.UUID}
AND organization_uuid = #{params.OrganizationUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
AND status = 'running'
AND session_external_id = ''

UPDATE evaluation_task_items
SET status = 'failed',
    error_message = #{params.ErrorMessage},
    updated_at = #{params.UpdatedAt}
WHERE uuid = #{params.UUID}
AND organization_uuid = #{params.OrganizationUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
AND status IN ('pending', 'running')
AND session_external_id = ''

UPDATE evaluation_task_items
SET status = #{params.Status},
    error_message = #{params.ErrorMessage},
    updated_at = #{params.UpdatedAt}
WHERE uuid = #{params.UUID}
AND organization_uuid = #{params.OrganizationUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
AND status = 'running'

UPDATE evaluation_task_items
SET updated_at = #{params.UpdatedAt}
WHERE uuid = #{params.UUID}
AND organization_uuid = #{params.OrganizationUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
AND status = 'running'

UPDATE evaluation_task_items
SET status = 'pending',
    session_external_id = '',
    error_message = '',
    updated_at = #{params.UpdatedAt}
WHERE organization_uuid = #{params.OrganizationUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
AND task_uuid = #{params.TaskUUID}
AND round = #{params.Round}
AND status = 'failed'

UPDATE evaluation_task_items
SET status = 'cancelled',
    updated_at = #{updatedAt}
WHERE organization_uuid = #{organizationUUID}
AND workspace_uuid = #{workspaceUUID}
AND task_uuid = #{taskUUID}
AND status IN ('pending', 'running')
RETURNING

UPDATE evaluation_tasks
SET status = 'cancelled',
    updated_at = #{updatedAt}
WHERE organization_uuid = #{organizationUUID}
AND workspace_uuid = #{workspaceUUID}
AND uuid = #{taskUUID}
AND status IN ('pending', 'running')

mapper.delete:
DELETE FROM evaluation_task_scores s
WHERE s.organization_uuid = #{params.OrganizationUUID}
AND s.workspace_uuid = #{params.WorkspaceUUID}
AND s.task_uuid = #{params.TaskUUID}
AND s.status = 'failed'
AND s.item_uuid IN (
    SELECT i.uuid
    FROM evaluation_task_items i
    WHERE i.organization_uuid = #{params.OrganizationUUID}
    AND i.workspace_uuid = #{params.WorkspaceUUID}
    AND i.task_uuid = #{params.TaskUUID}
    AND i.round = #{params.Round}
    AND i.status = 'completed'
)

mapper.update:
UPDATE evaluation_tasks
SET status = 'running',
    error_message = '',
    updated_at = #{params.UpdatedAt}
WHERE organization_uuid = #{params.OrganizationUUID}
AND workspace_uuid = #{params.WorkspaceUUID}
AND uuid = #{params.TaskUUID}
AND status IN ('completed', 'failed')

mapper.select:
SELECT 
FROM evaluation_task_items
WHERE (status = 'pending' OR (status = 'running' AND session_external_id = ''))
AND updated_at < #{updatedBefore}
ORDER BY updated_at ASC, uuid ASC
LIMIT #{limit}

SELECT
    COALESCE(SUM(judge_input_tokens), 0) AS judge_input_tokens,
    COALESCE(SUM(judge_output_tokens), 0) AS judge_output_tokens
FROM evaluation_task_scores
WHERE organization_uuid = #{organizationUUID}
AND workspace_uuid = #{workspaceUUID}
AND task_uuid = #{taskUUID}
